DROP TABLE IF EXISTS `listening_events`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `listening_events` (
  `event_id` varchar(30) NOT NULL,
  `listener_id` varchar(20) DEFAULT NULL,
  `track_id` varchar(20) DEFAULT NULL,
  `platform_id` varchar(20) DEFAULT NULL,
  `session_id` varchar(30) DEFAULT NULL,
  `played_at` text,
  `ms_played` text,
  `completed` text,
  `skipped` text,
  `saved` text,
  `shared` text,
  `repeat_play` text,
  `source_context` varchar(60) DEFAULT NULL,
  `device_type` varchar(50) DEFAULT NULL,
  `country_code` varchar(5) DEFAULT NULL,
  `network_type` varchar(20) DEFAULT NULL,
  `volume_level` text,
  `offline_mode` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`event_id`),
  KEY `idx_events_listener` (`listener_id`),
  KEY `idx_events_track` (`track_id`),
  KEY `idx_events_country` (`country_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
